    "questionAr": "خليتان إلكتروليتيتان متصلتان على التوالي تحتويان على محلولي $\\text{FeCl}_2$ و $\\text{FeCl}_3$ على الترتيب. إذا ترسب $5.6\\text{ g}$ من الحديد عند كاثود خلية $\\text{FeCl}_2$، فما كتلة الحديد المترسبة في نفس الوقت عند كاثود خلية $\\text{FeCl}_3$؟ ($\\text{Fe} = 56\\text{ g/mol}$)",
