    "difficulty": "hots",
    "questionEn": "During the electrolysis of acidified water using Hoffman's voltameter, a total gas volume of $67.2\\text{ mL}$ is collected at STP from both electrodes combined. What quantity of electricity in Coulombs was consumed?",
