    "correctIndex": 1,
    "hintEn": "Water splits: $2\\text{H}_2\\text{O} \\to 2\\text{H}_2 + \\text{O}_2$. 3 volumes of gas are produced per 4 Faradays.",
    "hintAr": "معادلة تفكك الماء: $2\\text{H}_2\\text{O} \\to 2\\text{H}_2 + \\text{O}_2$. ينتج 3 حجوم غازية لكل 4 فاراداي.",
