    "difficulty": "hots",
    "questionEn": "During the electrolysis of $1.0\\text{ L}$ of a concentrated aqueous sodium chloride solution, a charge of $0.02\\text{ Faradays}$ is passed. Assuming the solution volume remains constant and complete mixing occurs, the final $\\text{pH}$ of the solution at $25^\\circ\\text{C}$ is approximately:",
    "questionAr": "أثناء التحليل الكهربي لـ $1.0\\text{ L}$ من محلول مركز لكلوريد الصوديوم، أُمِرَّت كمية كهرباء قدرها $0.02\\text{ Faradays}$. بافتراض ثبوت الحجم وتمام الخلط، فإن قيمة $\\text{pH}$ النهائية للمحلول عند $25^\\circ\\text{C}$ تساوي تقريباً:",
