    "difficulty": "hots",
    "questionEn": "A metallic sheet with a total surface area of $200\\text{ cm}^2$ (both sides combined) is electroplated with nickel ($\\text{Ni} = 58.7\\text{ g/mol}$, density $\\rho = 8.9\\text{ g/cm}^3$) from a $\\text{Ni}^{2+}$ bath using a current of $5.0\\text{ A}$ for $1930\\text{ seconds}$. What is the thickness of the deposited nickel layer?",
    "questionAr": "صفيحة معدنية مساحتها الكلية $200\\text{ cm}^2$ (للوجهين معاً) طُليت بالنيكل ($\\text{Ni} = 58.7\\text{ g/mol}$، الكثافة $\\rho = 8.9\\text{ g/cm}^3$) من حمام $\\text{Ni}^{2+}$ بإمرار تيار $5.0\\text{ A}$ لمدة $1930\\text{ ثانية}$. ما سمك طبقة النيكل المترسبة؟",
